extern "C" void solve_assignment(const double* c, int n, int* out) {
 std::vector<double> p(n,0.0);
 std::vector<int> own(n,-1), asn(n,-1), q(n);
 double eps=.02; // costs lie in [0,sqrt(2)]
 while(eps > 1e-13) {
   std::fill(own.begin(),own.end(),-1); std::fill(asn.begin(),asn.end(),-1);
   int head=0,tail=n; for(int i=0;i<n;i++) q[i]=i;
