     int i=q[head++]; const double* r=c+(size_t)i*n;
     double x1=1e100,x2=1e100; int j1=-1;
     for(int j=0;j<n;j++) { double x=r[j]+p[j]; if(x<x1){x2=x1;x1=x;j1=j;} else if(x<x2)x2=x; }
     p[j1] += x2-x1+eps;
     int old=own[j1]; own[j1]=i; asn[i]=j1;
     if(old>=0) {asn[old]=-1; if(tail==(int)q.size()) q.resize(q.size()*2);q[tail++]=old;}
   }
   eps *= .1;
 }
 for(int i=0;i<n;i++)out[i]=asn[i];
}
